#include <algorithm>
#include <cstdio>
#include <cstring>
#include <exception>
#include <iostream>
#include <vector>
using namespace std;

struct node {
  int id, syn, inh;
  node(int id = 0, int syn = 0, int inh = 0) : id(id), syn(syn), inh(inh) {
  }
};
char ll1Idx[128];
int ll1Table[10][10];
vector<int> ssdTable[10];

inline int idx(char c) {
  return ll1Idx[c];
}

inline void initLL1Table() {
  memset(ll1Idx, 0, sizeof ll1Idx);
  memset(ll1Table, -1, sizeof ll1Table);

  for (int k = '0'; k <= '9'; ++k) ll1Idx[k] = 1;
  ll1Idx['('] = 2;
  ll1Idx[')'] = 3;
  ll1Idx['+'] = 4;
  ll1Idx['-'] = 5;
  ll1Idx['*'] = 6;
  ll1Idx['/'] = 7;
  ll1Idx['$'] = 8;

  ll1Idx['A'] = -1;
  ll1Idx['B'] = -2;
  ll1Idx['C'] = -3;
  ll1Idx['D'] = -4;
  ll1Idx['E'] = -5;

  // 0: A -> BD
  ll1Table[1][1] = 0;
  ll1Table[1][2] = 0;

  // 1: A -> +BD
  ll1Table[1][4] = 1;

  // 2: A -> -BD
  ll1Table[1][5] = 2;

  // 3: B --> CE
  ll1Table[2][1] = 3;
  ll1Table[2][2] = 3;

  // 4: C --> digit
  ll1Table[3][1] = 4;

  // 5: C --> (A)
  ll1Table[3][2] = 5;

  // 6: D --> +BD
  ll1Table[4][4] = 6;

  // 7: D --> -BD
  ll1Table[4][5] = 7;

  // 8: D --> \varepsilon
  ll1Table[4][3] = 8;
  ll1Table[4][8] = 8;

  // 9: E --> *CE
  ll1Table[5][6] = 9;

  // 10: E --> /CE
  ll1Table[5][7] = 10;

  // 11: E --> \varepsilon
  ll1Table[5][3] = 11;
  ll1Table[5][4] = 11;
  ll1Table[5][5] = 11;
  ll1Table[5][8] = 11;
}


inline void initSSDTable() {
#define pb push_back
  for (int i = 0; i < 10; ++i) ssdTable[i].clear();

  // 0: A --> BD
  ssdTable[0].pb(idx('B'));
  ssdTable[0].pb(idx('D'));

  // 1: A --> +BD
  ssdTable[1].pb(idx('+'));
  ssdTable[1].pb(idx('B'));
  ssdTable[1].pb(idx('D'));

  // 2: A --> -BD
  ssdTable[2].pb(idx('-'));
  ssdTable[2].pb(idx('B'));
  ssdTable[2].pb(idx('D'));

  // 3: B --> CE
  ssdTable[3].pb(idx('C'));
  ssdTable[3].pb(idx('E'));

  // 4: C --> digit
  ssdTable[4].pb(idx('0'));

  // 5: C -> (A)
  ssdTable[5].pb(idx('('));
  ssdTable[5].pb(idx('A'));
  ssdTable[5].pb(idx(')'));

  // 6: D --> +BD
  ssdTable[6].pb(idx('+'));
  ssdTable[6].pb(idx('B'));
  ssdTable[6].pb(idx('D'));

  // 7: D --> -BD
  ssdTable[7].pb(idx('-'));
  ssdTable[7].pb(idx('B'));
  ssdTable[7].pb(idx('D'));

  // 8: D --> \varepsilon

  // 9: E --> *CE
  ssdTable[9].pb(idx('*'));
  ssdTable[9].pb(idx('C'));
  ssdTable[9].pb(idx('E'));

  // 10: E --> /CE
  ssdTable[10].pb(idx('/'));
  ssdTable[10].pb(idx('C'));
  ssdTable[10].pb(idx('E'));

  // 11: E --> \varepsilon
#undef pb
}

int getnum(const char*& s) {
  int num = 0;
  for (; isdigit(*s); ++s) num = num * 10 + *s - '0';
  return num;
}

const int endsym = idx('$');
void calculate(const char*& s, node& sy, int cur) {
  int id = idx(*s);
  if (!id) throw "Syntax Error";

  if (sy.id != endsym) {
    if (sy.id == id) {
      if (id == 1) {
        sy.syn = getnum(s);
      } else {
        ++s;
      }
      return;
    }
    if (sy.id > 0) throw "Syntax Error!";

    int Mid = ll1Table[-sy.id][id];
    if (Mid < 0) throw "Syntax Error!";

    node sym[4];

    for (int i = 0; i < ssdTable[Mid].size(); ++i) sym[i].id = ssdTable[Mid][i];
    if (ssdTable[Mid].size()) calculate(s, sym[0], cur + 1);

    switch (Mid) {
      // 0: A --> BD
      case 0:
        sym[1].inh = sym[0].syn;
        calculate(s, sym[1], cur + 1);
        sy.syn = sym[1].syn;
        break;

      // 1: A --> +BD
      case 1:
        calculate(s, sym[1], cur + 1);
        sym[2].inh = sym[1].syn;
        calculate(s, sym[2], cur + 1);
        sy.syn = sym[2].syn;
        break;

      // 2: A --> -BD
      case 2:
        calculate(s, sym[1], cur + 1);
        sym[2].inh = -sym[1].syn;
        calculate(s, sym[2], cur + 1);
        sy.syn = sym[2].syn;
        break;

      // 3: B --> CE
      case 3:
        sym[1].inh = sym[0].syn;
        calculate(s, sym[1], cur + 1);
        sy.syn = sym[1].syn;
        break;

      // 4: C --> digit
      case 4:
        sy.syn = sym[0].syn;
        break;

      // 5: C --> (A)
      case 5:
        calculate(s, sym[1], cur + 1);
        sy.syn = sym[1].syn;
        calculate(s, sym[2], cur + 1);
        break;

      // 6: D --> +BD
      case 6:
        calculate(s, sym[1], cur + 1);
        sym[2].inh = sy.inh + sym[1].syn;
        calculate(s, sym[2], cur + 1);
        sy.syn = sym[2].syn;
        break;

      // 7: D --> -BD
      case 7:
        calculate(s, sym[1], cur + 1);
        sym[2].inh = sy.inh - sym[1].syn;
        calculate(s, sym[2], cur + 1);
        sy.syn = sym[2].syn;
        break;

      // 8: D --> \varepsilon
      case 8:
        sy.syn = sy.inh;
        break;

      // 9: E --> *CE
      case 9:
        calculate(s, sym[1], cur + 1);
        sym[2].inh = sy.inh * sym[1].syn;
        calculate(s, sym[2], cur + 1);
        sy.syn = sym[2].syn;
        break;

      // 10: E --> /CE
      case 10:
        calculate(s, sym[1], cur + 1);
        sym[2].inh = sy.inh / sym[1].syn;
        calculate(s, sym[2], cur + 1);
        sy.syn = sym[2].syn;
        break;

      // 11: E --> \varepsilon
      case 11:
        sy.syn = sy.inh;
        break;
    }
  }
}

int main() {
  string in;
  string coin;
  initLL1Table();
  initSSDTable();
  while (getline(cin, in)) {
    in.push_back('$');
    int len = in.length();
    const char* s = in.c_str();

    // 去除空格
    coin.clear();
    for (int i = 0; i < len; ++i)
      if (s[i] != ' ' && s[i] != '\t' && s[i] != '\n') coin.push_back(s[i]);
    coin.push_back('\0');

    try {
      node sy = node(idx('A'));
      s = coin.c_str();
      calculate(s, sy, 0);
      int ans = sy.syn;
      for (int i = 0; i < len - 1; ++i) putchar(in[i]);
      printf(" = %d\n", ans);
      printf("succuss!\n");
    } catch (const char* str) {
      puts(str);
    }
  }
  return 0;
}

export enum TokenSymbol {
  DIGIT = 1,
  OPEN_PAREN = 2,
  CLOSE_PAREN = 3,
  PLUS = 4,
  MINUS = 5,
  MULTI = 6,
  DIVIDE = 7,
  END = 8,
  A = -1,
  B = -2,
  C = -3,
  D = -4,
  E = -5,
}

/**
 * Priority map.
 */
const ll1IdxMap: Record<string, TokenSymbol> = Object.freeze({
  '0': TokenSymbol.DIGIT,
  '1': TokenSymbol.DIGIT,
  '2': TokenSymbol.DIGIT,
  '3': TokenSymbol.DIGIT,
  '4': TokenSymbol.DIGIT,
  '5': TokenSymbol.DIGIT,
  '6': TokenSymbol.DIGIT,
  '7': TokenSymbol.DIGIT,
  '8': TokenSymbol.DIGIT,
  '9': TokenSymbol.DIGIT,
  '(': TokenSymbol.OPEN_PAREN,
  ')': TokenSymbol.CLOSE_PAREN,
  '+': TokenSymbol.PLUS,
  '-': TokenSymbol.MINUS,
  '*': TokenSymbol.MULTI,
  '/': TokenSymbol.DIVIDE,
  $: TokenSymbol.END,
  A: TokenSymbol.A,
  B: TokenSymbol.B,
  C: TokenSymbol.C,
  D: TokenSymbol.D,
  E: TokenSymbol.E,
})

export const idx = (c: string): number => ll1IdxMap[c]

export const sddTable: number[][] = [
  'BD', //    0: A --> BD
  '+BD', //   1: A --> +BD
  '-BD', //   2: A --> -BD
  'CE', //    3: B --> CE
  '0', //     4: C --> digit
  '(A)', //   5: C --> (A)
  '+BD', //   6: D --> +BD
  '-BD', //   7: D --> -BD
  '', //      8: D --> \varepsilon
  '*CE', //   9: E --> *CE
  '/CE', //  10: E --> /CE
  '', //     11: E --> \varepsilon
].map(x => x.split('').map(idx))

// tokens: A,B,C,D,E
export const MAX_TOKENS = 5

// symbols: digit, (, ), +, -, *, /, $
export const MAX_SYMBOLS = 8

// LL1 table.
export const ll1Table: Int8Array[] = new Array(MAX_TOKENS + 1)

// Initialize LL1Table
{
  for (let i = 0; i <= MAX_TOKENS; ++i) {
    ll1Table[i] = new Int8Array(MAX_SYMBOLS + 1).fill(-1)
  }

  // 0: A -> BD
  ll1Table[1][1] = 0
  ll1Table[1][2] = 0

  // 1: A -> +BD
  ll1Table[1][4] = 1

  // 2: A -> -BD
  ll1Table[1][5] = 2

  // 3: B --> CE
  ll1Table[2][1] = 3
  ll1Table[2][2] = 3

  // 4: C --> digit
  ll1Table[3][1] = 4

  // 5: C --> (A)
  ll1Table[3][2] = 5

  // 6: D --> +BD
  ll1Table[4][4] = 6

  // 7: D --> -BD
  ll1Table[4][5] = 7

  // 8: D --> \varepsilon
  ll1Table[4][3] = 8
  ll1Table[4][8] = 8

  // 9: E --> *CE
  ll1Table[5][6] = 9

  // 10: E --> /CE
  ll1Table[5][7] = 10

  // 11: E --> \varepsilon
  ll1Table[5][3] = 11
  ll1Table[5][4] = 11
  ll1Table[5][5] = 11
  ll1Table[5][8] = 11
}

export function getNum(s: string, start: number): [number, number] {
  let result = 0
  let i: number = start
  for (; i < s.length; ++i) {
    const c = s[i]
    if (!/\d/.test(c)) break
    result = result * 10 + Number(c)
  }
  return [i, result]
}

export function calculate(rawExpression: string): number {
  let cur = 0
  const expression = rawExpression.replace(/[\s]+/g, '')
  const result: number = dfs(idx('A'), 0, 0)
  return cur === expression.length ? result : Number.NaN

  function dfs(id: number, syn: number, inh: number): number {
    if (cur === expression.length) {
      // Only D and E could be parsed as \varepsilon
      if (id === TokenSymbol.D || id === TokenSymbol.E) return inh
      return Number.NaN
    }

    const id0 = idx(expression[cur])

    // Unrecognized symbol.
    if (id0 === undefined) return Number.NaN

    // Matched an operator.
    if (id === id0) {
      // Matched digits.
      if (id0 === TokenSymbol.DIGIT) {
        const [nextCur, value] = getNum(expression, cur)

        // No valid digit found.
        if (cur === nextCur) return Number.NaN

        cur = nextCur
        return value
      }

      cur += 1
      return syn
    }

    // Syntax error.
    if (id > 0) return Number.NaN

    const ssdId = ll1Table[-id][id0]
    if (ssdId < 0) return Number.NaN

    const tokens: ReadonlyArray<number> = sddTable[ssdId]
    const syn0: number = tokens.length > 0 ? dfs(tokens[0], 0, 0) : 0

    switch (ssdId) {
      // 0: A --> BD
      case 0:
        return dfs(tokens[1], 0, syn0)

      // 1: A --> +BD
      case 1: {
        const val1: number = dfs(tokens[1], 0, 0)
        return dfs(tokens[2], 0, val1)
      }

      // 2: A --> -BD
      case 2: {
        const val1: number = dfs(tokens[1], 0, 0)
        return dfs(tokens[2], 0, -val1)
      }

      // 3: B --> CE
      case 3:
        return dfs(tokens[1], 0, syn0)

      // 4: C --> digit
      case 4:
        return syn0

      // 5: C --> (A)
      case 5: {
        const result: number = dfs(tokens[1], 0, 0)
        dfs(tokens[2], 0, 0)
        return result
      }

      // 6: D --> +BD
      case 6: {
        const val1: number = dfs(tokens[1], 0, 0)
        return dfs(tokens[2], 0, inh + val1)
      }

      // 7: D --> -BD
      case 7: {
        const val1: number = dfs(tokens[1], 0, 0)
        return dfs(tokens[2], 0, inh - val1)
      }

      // 8: D --> \varepsilon
      case 8:
        return inh

      // 9: E --> *CE
      case 9: {
        const val1: number = dfs(tokens[1], 0, 0)
        return dfs(tokens[2], 0, inh * val1)
      }

      // 10: E --> /CE
      case 10: {
        const val1: number = dfs(tokens[1], 0, 0)
        return dfs(tokens[2], 0, inh / val1)
      }

      // 11: E --> \varepsilon
      case 11:
        return inh
    }

    return 0
  }
}
